function splitGroundedClaims(text) {
  if(typeof text!=='string'||!text.trim())throw new Error('Article text is empty.');
  const dates=[...text.matchAll(/\b\d{1,2}\.\s*(?:(?:Januar|Februar|März|April|Mai|Juni|Juli|August|September|Oktober|November|Dezember)|\d{1,2}\.)\s*\d{2,4}\b/gi)].map(match=>[match.index,match.index+match[0].length]);
  const lists=[...text.matchAll(/^\s*\d+\.\s+/gm)].map(match=>[match.index,match.index+match[0].length]);
  const protectedRanges=[...dates,...lists].sort((a,b)=>a[0]-b[0]);
  let protectedIndex=0;
  const boundaries=[...text.matchAll(/(?<=[.!?])\s+(?=[A-ZÄÖÜ]|$)/g)].filter(match=>{
    while(protectedIndex<protectedRanges.length&&protectedRanges[protectedIndex][1]<=match.index)protectedIndex++;
    const range=protectedRanges[protectedIndex];
    return !range||match.index<=range[0]||match.index>=range[1];
  });
  const claims=[];let offset=0;for(const boundary of boundaries){const claim=text.slice(offset,boundary.index).trim();if(claim)claims.push(claim);offset=boundary.index+boundary[0].length;}const last=text.slice(offset).trim();if(last)claims.push(last);return claims;
}
function prepareGroundedClaims({documents}){
  if(!Array.isArray(documents))throw new Error('Provide an array of facts/text document pairs.');
  const claims=[];
  for(const [documentIndex,document] of documents.entries()){
    if(!document||typeof document.facts!=='string'||!document.facts.trim())throw new Error('Reference facts are empty.');
    for(const [claimIndex,claim] of splitGroundedClaims(document.text).entries())claims.push({documentIndex,claimIndex,claim});
  }
  return {documents,claims};
}

return [{json:prepareGroundedClaims({documents:$input.all().map(item=>({facts:item.json.facts,text:item.json.text}))}),pairedItem:{item:0}}];

function validateMiniCheckText(content){if(typeof content!=='string')throw new Error('Bespoke-MiniCheck answer is not text.');const verdict=content.trim();if(verdict!=='Yes'&&verdict!=='No')throw new Error('Bespoke-MiniCheck must answer Yes or No.');return verdict;}
function readMiniCheckVerdict(response){
  if(!response||typeof response!=='object'||response.done!==true||response.model!=='bespoke-minicheck:latest'||response.message?.role!=='assistant'||typeof response.message.content!=='string')throw new Error('Ollama did not return a complete bespoke-minicheck answer.');
  return validateMiniCheckText(response.message.content);
}

const plan=$("Prepare Claim Batch").first().json,items=$input.all();if(plan.claims.length&&items.length!==plan.claims.length)throw new Error("Claim judgment count differs from input.");const checks=plan.claims.map((claim,index)=>({...claim,verdict:validateMiniCheckText(items[index].json.text)})),unsupported=checks.filter(item=>item.verdict==="No");return [{json:{checks,unsupported,count:unsupported.length,summaryInput:JSON.stringify(unsupported)},pairedItem:{item:0}}];

function finishGroundedReport({checks,unsupported,completion}){
  if(!Array.isArray(checks)||!Array.isArray(unsupported))throw new Error('Grounded check results are missing.');
  const summary=unsupported.length===0?'No unsupported claims were identified by the configured checker.':completion;
  if(typeof summary!=='string'||!summary.trim())throw new Error('The grounded-check summary is empty.');
  return {checks,unsupported,count:unsupported.length,summary:summary.trim()};
}

const checked=$("Collect All Claim Checks").first().json;return [{json:finishGroundedReport({...checked,completion:$input.first().json.text??null}),pairedItem:{item:0}}];
